export const COORDINATE_GEOMETRY_ACTIVITIES = [
{n:1,type:"mcq",micro:"Kuadran pada peta kota",q:"Sebuah peta kota dibagi menjadi empat bagian oleh dua jalan utama yang saling tegak lurus: Jalan Utara-Selatan dan Jalan Timur-Barat. Berapa banyak bagian (kuadran) yang terbentuk?",options:["4 bagian","2 bagian","3 bagian"],answer:0,explain:"Dua garis yang saling tegak lurus membagi bidang menjadi 4 bagian, seperti dua sumbu koordinat membentuk 4 kuadran.",hint:"Bayangkan dua jalan yang saling memotong tegak lurus di tengah kota — ada berapa 'kotak besar' yang terbentuk?"},
{n:2,type:"mcq",micro:"Dua angka untuk satu posisi",q:"Rumahmu berada 3 blok ke timur dan 2 blok ke utara dari alun-alun kota. Informasi apa yang kamu butuhkan untuk menjelaskan lokasi rumahmu dengan tepat kepada seseorang?",options:["Hanya satu angka sudah cukup","Dua angka: jarak ke timur DAN jarak ke utara","Warna rumahmu"],answer:1,explain:"Posisi pada bidang datar membutuhkan dua informasi arah yang berbeda (horizontal dan vertikal) agar tepat.",hint:"Apakah hanya menyebut '3 blok' saja sudah cukup jelas, tanpa menyebutkan ke arah utara atau ke arah lain?"},
{n:3,type:"mcq",micro:"Jarak konkret di sepanjang jalan",q:"Dua rumah berada di jalan yang sama, satu di posisi 3 dan satu di posisi 8 (dihitung dari ujung jalan). Berapa jarak antara kedua rumah tersebut?",options:["11 satuan","3 satuan","5 satuan"],answer:2,explain:"Jarak di sepanjang garis lurus yang sama dihitung dengan mengurangkan posisi yang lebih kecil dari posisi yang lebih besar: 8−3=5.",hint:"Kurangkan posisi yang lebih kecil dari posisi yang lebih besar."},
{n:4,type:"mcq",micro:"Refleksi konkret (cermin)",q:"Kamu berdiri di depan cermin dan mengangkat tangan kananmu. Tangan mana yang tampak terangkat pada bayanganmu di cermin?",options:["Tangan kiri bayangan (karena cermin membalik sisi kiri-kanan)","Tangan kanan bayangan (karena cermin tidak membalik sisi)","Kedua tangan bayangan terangkat (karena cermin menggandakan gerak)"],answer:0,explain:"Cermin membalik sisi kiri dan kanan, sehingga tangan kanan asli tampak seperti tangan kiri pada bayangan.",hint:"Coba bayangkan dirimu sendiri di depan cermin — apakah bayanganmu benar-benar identik, atau terbalik sisi kiri-kanannya?"},
{n:5,type:"mcq",micro:"Translasi konkret (menggeser benda)",q:"Sebuah buku digeser 5 cm ke kanan di atas meja, tanpa diputar atau dibalik. Apa yang terjadi pada bentuk dan ukuran buku tersebut?",options:["Bentuknya sama tetapi ukurannya mengecil sedikit karena bergeser","Bentuk dan ukurannya tetap sama, hanya posisinya yang berubah","Ukurannya sama tetapi bentuknya berubah karena posisinya bergeser"],answer:1,explain:"Menggeser (translasi) suatu benda tanpa memutar atau membaliknya tidak mengubah bentuk maupun ukurannya, hanya posisinya.",hint:"Apakah menggeser sebuah buku di atas meja mengubah bentuknya, atau hanya memindahkan posisinya?"},
{n:6,type:"mcq",micro:"Bentuk konkret pada papan paku",q:"Pada papan paku, sebuah karet gelang dipasang mengelilingi 4 paku yang membentuk sudut siku-siku dan semua sisinya sama panjang. Bentuk apa yang terbentuk?",options:["Segitiga","Lingkaran","Persegi"],answer:2,explain:"Empat sisi sama panjang dengan sudut siku-siku semua adalah ciri khas sebuah persegi.",hint:"Bentuk apa yang memiliki 4 sisi sama panjang dan 4 sudut siku-siku?"},
{n:7,type:"mcq",micro:"Posisi dari dua arah (konkret)",q:"Sebuah kapal berlayar dari pelabuhan lurus ke arah timur sejauh 6 km, lalu berbelok dan berlayar lurus ke utara sejauh 8 km. Informasi apa yang dibutuhkan untuk menandai posisi akhir kapal pada peta?",options:["Posisi akhirnya bisa ditandai menggunakan dua jarak tersebut: 6 km timur dan 8 km utara dari titik awal","Posisi akhirnya hanya bisa ditandai dengan satu angka saja, yaitu 14 km dari titik awal","Posisi akhirnya tidak bisa ditentukan karena kapal berbelok ke arah yang berbeda dari awal"],answer:0,explain:"Menggabungkan jarak ke timur dan jarak ke utara memberikan posisi akhir yang tepat, seperti koordinat (x, y).",hint:"Apakah kamu bisa menandai posisi akhir kapal di peta hanya dengan mengetahui satu dari dua jarak tersebut?"},
{n:8,type:"mcq",micro:"Menghitung jarak sepanjang garis lurus",q:"Dua titik berada pada garis lurus horizontal yang sama. Titik A di posisi 2 dan titik B di posisi 9. Bagaimana cara termudah mencari jarak di antara keduanya?",options:["Jumlahkan kedua posisi dan bagi dengan dua: (2+9)÷2 = 5,5","Kurangkan posisi yang lebih besar dengan yang lebih kecil: 9 − 2 = 7","Kalikan kedua posisi lalu kurangi dengan angka satu: 2×9 − 1 = 17"],answer:1,explain:"Jarak antara dua titik pada garis lurus yang sama adalah selisih posisinya.",hint:"Apakah menjumlahkan atau mengalikan posisi kedua titik masuk akal untuk mencari jarak di antara keduanya?"},
{n:9,type:"mcq",micro:"Translasi pada pola ubin",q:"Sebuah pola ubin lantai dibuat dengan menggeser satu motif yang sama berulang kali ke kanan, tanpa memutar atau membaliknya. Apa istilah untuk gerakan menggeser seperti ini dalam geometri?",options:["Refleksi (pencerminan)","Rotasi (perputaran)","Translasi"],answer:2,explain:"Menggeser suatu bentuk tanpa memutar atau membaliknya disebut translasi.",hint:"Apakah motif tersebut diputar, dibalik seperti cermin, atau hanya digeser lurus?"},
{n:10,type:"mcq",micro:"Refleksi pada bayangan air",q:"Bayangan sebuah pohon di permukaan danau yang tenang tampak terbalik atas-bawah dibandingkan pohon aslinya. Peristiwa ini adalah contoh dari apa?",options:["Refleksi (pencerminan)","Translasi (pergeseran)","Rotasi (perputaran)"],answer:0,explain:"Bayangan yang terbalik pada permukaan air adalah contoh nyata dari pencerminan (refleksi).",hint:"Apakah bayangan pohon tersebut hanya digeser, atau justru dibalik seperti pada cermin?"},
{n:11,type:"mcq",micro:"Mencatat posisi dengan dua angka",q:"Seorang anak berjalan 4 langkah ke kanan dari titik awal, lalu 3 langkah ke atas. Bagaimana cara paling jelas mencatat posisi akhirnya?",options:["Sebagai satu angka saja: 7 langkah dari titik awal","Sebagai pasangan dua angka: (4 langkah kanan, 3 langkah atas)","Sebagai dua angka yang dikalikan: 4 × 3 = 12 langkah"],answer:1,explain:"Posisi akhir membutuhkan dua informasi terpisah (horizontal dan vertikal) agar bisa dijelaskan dengan tepat.",hint:"Apakah menjumlahkan 4 dan 3 menjadi 7 langkah masih menunjukkan posisi akhir dengan tepat?"},
{n:12,type:"mcq",micro:"Posisi relatif pada denah rumah",q:"Pada denah rumah, kamar tidur berada di sebelah kanan-atas, sedangkan dapur berada di sebelah kiri-bawah. Apa yang menentukan posisi relatif ini?",options:["Hanya jarak antara kedua kamar dan ukuran kamar tidur pada denah","Hanya jenis lantai dan warna cat di kamar tidur serta dapur pada denah","Kombinasi arah horizontal (kanan/kiri) dan arah vertikal (atas/bawah)"],answer:2,explain:"Menjelaskan posisi suatu ruangan membutuhkan gabungan arah horizontal dan vertikal sekaligus.",hint:"Apakah kata 'kanan-atas' menggabungkan dua arah, atau hanya satu arah saja?"},
{n:13,type:"mcq",micro:"Mengukur jarak horizontal",q:"Dua titik lampu berada pada tinggi yang sama tetapi berbeda posisi mendatar: satu di ujung kiri ruangan, satu di ujung kanan. Bagaimana cara mengukur jarak horizontal di antara keduanya?",options:["Menghitung jarak mendatar langsung antara kedua posisi tersebut","Menghitung jarak tegak antara tinggi kedua lampu","Menjumlahkan posisi kedua lampu lalu membaginya dengan dua"],answer:0,explain:"Karena kedua titik memiliki tinggi yang sama, jarak di antara keduanya cukup diukur secara mendatar saja.",hint:"Karena kedua lampu memiliki tinggi yang sama, arah mana yang perlu diukur untuk mencari jaraknya?"},
{n:14,type:"mcq",micro:"Menandai titik secara presisi",q:"Sebuah titik pada peta berada tepat di persilangan antara sebuah jalan dan sebuah sungai. Informasi apa yang dibutuhkan untuk menandai titik tersebut secara presisi pada peta?",options:["Hanya nama jalan atau nama sungai, tanpa posisi terhadap titik acuan apa pun pada peta","Posisi horizontal DAN posisi vertikalnya terhadap suatu titik acuan (seperti pusat kota)","Hanya panjang total sungai dan jalan itu, tanpa perlu mengetahui letak persilangannya"],answer:1,explain:"Menandai titik secara presisi pada bidang datar membutuhkan posisi horizontal dan vertikal terhadap suatu titik acuan.",hint:"Apakah menyebutkan nama jalan saja sudah cukup untuk menandai satu titik tepat di peta?"},
{n:15,type:"mcq",micro:"Translasi mempertahankan bentuk",q:"Sebuah bentuk digeser 3 satuan ke kanan dan 2 satuan ke atas, tanpa diputar. Apakah bentuk barunya sama persis dengan bentuk aslinya?",options:["Tidak, ukurannya berubah menjadi lebih besar karena bergeser","Tidak, bentuknya menjadi miring karena digeser ke kanan dan atas","Ya, bentuk dan ukurannya identik, hanya posisinya yang berbeda"],answer:2,explain:"Translasi murni (hanya menggeser) tidak pernah mengubah bentuk atau ukuran suatu objek.",hint:"Apakah menggeser suatu bentuk tanpa memutar atau membaliknya bisa mengubah bentuknya?"},
{n:16,type:"mcq",micro:"Informasi minimum posisi pada kertas berpetak",q:"Pada sebuah kertas berpetak (kotak-kotak kecil), kamu ingin mendeskripsikan posisi sebuah titik. Apa dua informasi minimum yang kamu butuhkan?",options:["Berapa kotak ke kanan/kiri, dan berapa kotak ke atas/bawah dari suatu titik awal","Berapa kotak ke kanan/kiri saja, karena posisi atas/bawah bisa ditebak dari gambar","Berapa banyak kotak seluruhnya pada kertas, dan berapa kotak yang sudah diwarnai"],answer:0,explain:"Posisi pada bidang datar selalu membutuhkan dua informasi arah agar dapat ditentukan dengan tepat.",hint:"Apakah satu informasi arah saja (misalnya hanya 'ke kanan') sudah cukup menunjukkan satu titik tertentu?"},
{n:17,type:"mcq",micro:"Mengapa lintang dan bujur butuh dua angka",q:"Seorang pelaut menggunakan dua angka — lintang dan bujur — untuk menandai posisi kapalnya di lautan. Mengapa dua angka dibutuhkan, bukan hanya satu?",options:["Karena permukaan bumi hanya punya satu arah penting, dan angka kedua dipakai sebagai cadangan jika angka pertama tidak jelas","Karena permukaan bumi (seperti bidang datar) memiliki dua arah independen (utara-selatan dan timur-barat) yang harus ditentukan bersamaan","Karena kapal bergerak di dua lautan berbeda sehingga masing-masing lautan memiliki satu angka untuk posisi yang dicatat"],answer:1,explain:"Dua arah independen (utara-selatan dan timur-barat) membutuhkan dua angka agar posisi bisa ditentukan secara tepat.",hint:"Apakah satu angka saja bisa menunjukkan posisi yang membutuhkan dua arah berbeda sekaligus?"},
{n:18,type:"mcq",micro:"Jarak di sepanjang baris pada kompleks grid",q:"Dua rumah berada pada baris yang sama di sebuah kompleks perumahan berbentuk grid (kotak-kotak). Untuk mencari jarak di antara keduanya jika hanya bergerak lurus di sepanjang baris, apa yang perlu dilakukan?",options:["Menjumlahkan nomor kedua rumah di sepanjang baris tersebut","Mengukur luas halaman kedua rumah di baris perumahan itu","Menghitung selisih posisi kedua rumah di sepanjang baris tersebut"],answer:2,explain:"Karena kedua rumah berada pada baris yang sama, jaraknya cukup dihitung sebagai selisih posisi di sepanjang baris itu.",hint:"Karena kedua rumah berada pada baris yang sama, apakah yang dibutuhkan hanya selisih posisi mereka?"},
{n:19,type:"mcq",micro:"Posisi berlawanan terhadap titik acuan",q:"Sebuah titik berada di kanan sekaligus di atas suatu titik acuan (titik nol). Titik lain berada di kiri sekaligus di bawah titik acuan yang sama. Apa yang bisa dikatakan tentang kedua titik ini?",options:["Kedua titik berada di sisi yang berlawanan sepenuhnya terhadap titik acuan","Kedua titik berada di sisi yang sama persis terhadap titik acuan itu","Kedua titik berada tepat di titik acuan yang sama pada denah"],answer:0,explain:"Kanan-atas dan kiri-bawah adalah dua sisi yang benar-benar berlawanan terhadap titik acuan yang sama.",hint:"Apakah kanan-atas dan kiri-bawah menunjuk ke arah yang sama, atau ke arah yang berlawanan?"},
{n:20,type:"mcq",micro:"Memeriksa klaim tentang posisi titik",q:"Seseorang berkata bahwa 'posisi suatu titik pada bidang datar hanya bisa dijelaskan dengan kata-kata, bukan dengan angka.' Apakah pernyataan ini benar?",options:["Benar — posisi titik pada bidang datar tidak bisa dijelaskan dengan angka karena angka hanya untuk garis lurus","Salah — posisi titik pada bidang datar bisa dijelaskan secara tepat menggunakan dua angka (koordinat)","Benar — hanya benda yang bergerak yang bisa dijelaskan posisinya dengan angka, sedangkan titik diam tidak"],answer:1,explain:"Koordinat (dua angka) justru cara yang paling tepat dan konsisten untuk menjelaskan posisi suatu titik.",hint:"Apakah dua angka seperti (3, 5) bisa menunjukkan posisi suatu titik secara tepat, tanpa perlu kata-kata panjang?"},
{n:21,type:"mcq",micro:"Membaca koordinat dari gambar",q:"Sebuah titik digambar 4 satuan ke kanan dan 3 satuan ke atas dari titik pusat (0,0). Bagaimana titik ini ditulis sebagai pasangan koordinat?",options:["(3, 4)","(4, -3)","(4, 3)"],answer:2,explain:"Urutan penulisan koordinat adalah (horizontal, vertikal): 4 ke kanan, 3 ke atas.",hint:"Angka mana yang ditulis lebih dulu dalam pasangan koordinat — pergerakan mendatar atau pergerakan naik-turun?"},
{n:22,type:"mcq",micro:"Koordinat negatif dari gambar",q:"Sebuah titik digambar 2 satuan ke KIRI dan 5 satuan ke ATAS dari titik pusat. Bagaimana koordinat x-nya ditulis?",options:["-2","2","-5"],answer:0,explain:"Pergerakan ke kiri dari titik pusat ditulis sebagai koordinat x negatif.",hint:"Apakah bergerak ke kiri dari titik pusat menghasilkan koordinat x positif atau negatif?"},
{n:23,type:"mcq",micro:"Menentukan kuadran dari gambar",q:"Titik (3, -4) berada di kuadran mana pada bidang koordinat (x positif, y negatif)?",options:["Kuadran I (kanan-atas)","Kuadran IV (kanan-bawah)","Kuadran III (kiri-bawah)"],answer:1,explain:"x positif dan y negatif menunjukkan posisi kanan-bawah, yaitu Kuadran IV.",hint:"Jika x positif berarti ke kanan, dan y negatif berarti ke bawah, di sudut mana titik itu berada?"},
{n:24,type:"mcq",micro:"Menentukan kuadran dari gambar",q:"Titik (-5, -2) berada di kuadran mana (x negatif, y negatif)?",options:["Kuadran II (kiri-atas)","Kuadran IV (kanan-bawah)","Kuadran III (kiri-bawah)"],answer:2,explain:"x negatif dan y negatif menunjukkan posisi kiri-bawah, yaitu Kuadran III.",hint:"Jika x negatif berarti ke kiri, dan y negatif berarti ke bawah, di sudut mana titik itu berada?"},
{n:25,type:"order",micro:"Mengurutkan langkah pencerminan pada gambar",q:"Urutkan langkah-langkah berikut untuk mencerminkan titik (3, 2) terhadap sumbu-x pada gambar.",items:["Titik hasil pencerminan berada di (3, -2)","Gambar titik asli (3, 2) pada bidang koordinat","Bayangkan sumbu-x sebagai 'cermin', lalu balikkan jarak titik ke arah bawah dengan jarak yang sama"],answer:[1,2,0],explain:"Mulai dengan menggambar titik asli, lalu bayangkan proses pencerminannya, baru diperoleh titik hasil.",hint:"Bisakah kamu menentukan titik hasil pencerminan sebelum menggambar titik aslinya terlebih dahulu?"},
{n:26,type:"mcq",micro:"Refleksi terhadap sumbu-y pada gambar",q:"Pada gambar bidang koordinat, sebuah titik dan bayangan pencerminannya terhadap sumbu-y digambar. Jika titik asli berada di (4, 5), di mana posisi bayangannya?",options:["(-4, 5)","(4, -5)","(-4, -5)"],answer:0,explain:"Pencerminan terhadap sumbu-y membalik tanda koordinat x, sementara koordinat y tetap sama.",hint:"Pencerminan terhadap sumbu-y mengubah tanda koordinat yang mana — x atau y?"},
{n:27,type:"mcq",micro:"Translasi pada gambar",q:"Sebuah titik di gambar berada di (2, 3). Titik tersebut kemudian digeser (ditranslasikan) 3 satuan ke kanan dan 1 satuan ke bawah. Di mana posisi barunya?",options:["(5, 4)","(5, 2)","(-1, 2)"],answer:1,explain:"Tambahkan 3 pada koordinat x (2+3=5) dan kurangkan 1 dari koordinat y (3−1=2).",hint:"Ke kanan berarti menambah koordinat x, dan ke bawah berarti mengurangi koordinat y."},
{n:28,type:"mcq",micro:"Jarak horizontal dari gambar grid",q:"Pada gambar grid, dua titik berada pada baris horizontal yang sama: (2, 4) dan (7, 4). Berapa jarak di antara keduanya, dihitung langsung dari gambar?",options:["9 satuan","4 satuan","5 satuan"],answer:2,explain:"Karena kedua titik memiliki koordinat y yang sama, jaraknya adalah selisih koordinat x: 7−2=5.",hint:"Karena kedua titik berada pada baris yang sama, cukup hitung selisih koordinat x-nya saja."},
{n:29,type:"mcq",micro:"Jarak vertikal dari gambar grid",q:"Pada gambar grid, dua titik berada pada kolom vertikal yang sama: (3, 1) dan (3, 6). Berapa jarak di antara keduanya?",options:["5 satuan","7 satuan","3 satuan"],answer:0,explain:"Karena kedua titik memiliki koordinat x yang sama, jaraknya adalah selisih koordinat y: 6−1=5.",hint:"Karena kedua titik berada pada kolom yang sama, cukup hitung selisih koordinat y-nya saja."},
{n:30,type:"classify",micro:"Mengelompokkan titik berdasarkan kuadran",q:"Kelompokkan setiap titik berikut berdasarkan kuadrannya.",items:["(3, 5)","(-2, 4)","(-6, -1)","(7, -3)"],groups:["Kuadran I","Kuadran II","Kuadran III","Kuadran IV"],answer:{"Kuadran I":["(3, 5)"],"Kuadran II":["(-2, 4)"],"Kuadran III":["(-6, -1)"],"Kuadran IV":["(7, -3)"]},explain:"Kuadran I: x dan y positif; Kuadran II: x negatif, y positif; Kuadran III: x dan y negatif; Kuadran IV: x positif, y negatif.",hint:"Periksa tanda (positif/negatif) dari koordinat x dan y pada setiap titik."},
{n:31,type:"mcq",micro:"Titik tengah dari gambar (koordinat y sama)",q:"Pada gambar, titik tengah antara dua titik A(2, 2) dan B(6, 2) digambar. Karena kedua titik memiliki nilai y yang sama, apa nilai y dari titik tengahnya?",options:["4","2 (sama seperti kedua titik asal)","0"],answer:1,explain:"Jika kedua titik memiliki nilai y yang sama, titik tengahnya juga memiliki nilai y yang sama persis.",hint:"Jika kedua titik berada pada ketinggian yang sama, apakah titik tengahnya berada pada ketinggian yang berbeda?"},
{n:32,type:"mcq",micro:"Perkiraan visual titik tengah",q:"Melihat gambar titik tengah antara A(0, 0) dan B(8, 0), di mana kira-kira letak titik tengah tersebut secara visual?",options:["Di posisi (8, 0), sama seperti titik B","Di posisi (0, 0), sama seperti titik A","Tepat di tengah-tengah, pada posisi (4, 0)"],answer:2,explain:"Titik tengah selalu berada tepat di tengah-tengah jarak antara kedua titik asal.",hint:"Apakah titik tengah seharusnya lebih dekat ke salah satu titik, atau berjarak sama dari keduanya?"},
{n:33,type:"mcq",micro:"Membaca sisi segitiga dari gambar",q:"Sebuah segitiga digambar dengan titik-titik sudut di (0,0), (4,0), dan (0,3). Apa yang bisa dikatakan tentang sisi dari (0,0) ke (4,0)?",options:["Sisi tersebut horizontal (mendatar), sepanjang 4 satuan","Sisi tersebut vertikal (tegak), sepanjang 3 satuan","Sisi tersebut miring, sepanjang 5 satuan"],answer:0,explain:"Karena kedua titik memiliki koordinat y yang sama (keduanya 0), sisi tersebut horizontal.",hint:"Apakah koordinat y dari kedua titik itu sama, yang berarti sisi tersebut mendatar?"},
{n:34,type:"mcq",micro:"Garis sejajar dari gambar",q:"Pada gambar, garis A memiliki kemiringan (slope) yang sama dengan garis B, tetapi memotong sumbu-y di titik yang berbeda. Apa hubungan kedua garis ini?",options:["Tegak lurus","Sejajar (tidak akan pernah berpotongan)","Merupakan garis yang persis sama"],answer:1,explain:"Kemiringan yang sama tetapi titik potong sumbu-y berbeda menunjukkan dua garis yang sejajar.",hint:"Jika dua garis naik dengan kecepatan yang sama tetapi mulai dari ketinggian berbeda, akankah keduanya pernah bertemu?"},
{n:35,type:"mcq",micro:"Garis tegak lurus dari gambar",q:"Pada gambar, garis A tampak naik dari kiri ke kanan, sedangkan garis B tampak turun dari kiri ke kanan, dan keduanya berpotongan membentuk sudut yang terlihat seperti sudut siku-siku. Kemungkinan besar, apa hubungan kedua garis ini?",options:["Sejajar","Merupakan garis yang sama","Tegak lurus (saling membentuk sudut 90°)"],answer:2,explain:"Dua garis yang berpotongan membentuk sudut 90° disebut tegak lurus.",hint:"Apakah sudut yang terbentuk di antara kedua garis terlihat seperti sudut siku-siku (90°)?"},
{n:36,type:"mcq",micro:"Bagian yang tidak berubah saat refleksi",q:"Melanjutkan gambar refleksi titik (4,5) terhadap sumbu-y menjadi (-4,5): apa yang TIDAK berubah dari koordinat titik tersebut?",options:["Nilai y-nya (5) tetap sama","Nilai x-nya tetap sama","Kedua nilai x dan y berubah"],answer:0,explain:"Refleksi terhadap sumbu-y hanya membalik tanda koordinat x; koordinat y tidak berubah.",hint:"Bandingkan (4,5) dan (-4,5) — angka mana yang tetap sama?"},
{n:37,type:"mcq",micro:"Arah jarak dari koordinat x yang sama",q:"Sebuah peta digital menunjukkan dua lokasi: satu di (3, 8) dan satu di (3, 2). Karena nilai x keduanya sama, ke arah mana jarak di antara keduanya diukur?",options:["Horizontal (kiri-kanan)","Vertikal (atas-bawah)","Diagonal"],answer:1,explain:"Jika koordinat x sama, perbedaan hanya terjadi pada koordinat y, sehingga jaraknya vertikal.",hint:"Karena posisi horizontalnya sama persis, arah mana yang membedakan kedua titik ini?"},
{n:38,type:"mcq",micro:"Menjembatani gambar ke abstrak (translasi)",q:"Melihat beberapa contoh translasi pada gambar (titik selalu bergeser dengan jarak dan arah yang sama, tanpa berputar atau berubah bentuk), pola apa yang kamu perhatikan?",options:["Setiap translasi mengubah bentuk dan ukuran, sehingga bentuk akhir berbeda","Setiap translasi memutar bentuk sambil mempertahankan ukurannya saja","Setiap translasi mempertahankan bentuk dan ukuran, hanya mengubah posisi"],answer:2,explain:"Translasi, dalam contoh apa pun, selalu menggeser posisi tanpa mengubah bentuk atau ukuran.",hint:"Apakah bentuk dan ukuran objek berubah pada setiap contoh translasi yang kamu lihat?"},
{n:39,type:"mcq",micro:"Panjang sisi persegi dari gambar",q:"Pada gambar grid, sebuah taman berbentuk persegi memiliki titik-titik sudut di (1,1), (1,5), (5,5), dan (5,1). Berapa panjang salah satu sisinya, dihitung dari gambar?",options:["4 satuan","5 satuan","1 satuan"],answer:0,explain:"Selisih koordinat antara (1,1) dan (1,5) adalah 5−1=4, yaitu panjang sisi tersebut.",hint:"Hitung selisih koordinat y antara (1,1) dan (1,5)."},
{n:40,type:"mcq",micro:"Strategi memeriksa hubungan dua garis",q:"Untuk menentukan apakah dua garis pada gambar sejajar, tegak lurus, atau tidak keduanya, pendekatan apa yang membantu?",options:["Membandingkan panjang kedua garis tersebut saja","Membandingkan kemiringan (slope) kedua garis tersebut","Menghitung jumlah kotak yang dilewati kedua garis"],answer:1,explain:"Kemiringan (slope) adalah kunci untuk menentukan hubungan sejajar atau tegak lurus antara dua garis.",hint:"Apakah kemiringan kedua garis bisa memberi tahu kamu hubungan sejajar atau tegak lurus secara pasti?"},
{n:41,type:"mcq",micro:"Rumus jarak",q:"Hitung jarak antara titik (0, 0) dan (3, 4) menggunakan rumus jarak (teorema Pythagoras).",options:["7 satuan","12 satuan","5 satuan"],answer:2,explain:"Jarak = √(3² + 4²) = √(9+16) = √25 = 5.",hint:"Kuadratkan selisih x dan selisih y, jumlahkan, lalu akarkan hasilnya."},
{n:42,type:"mcq",micro:"Rumus jarak",q:"Hitung jarak antara titik (1, 1) dan (4, 5).",options:["5 satuan","4 satuan","9 satuan"],answer:0,explain:"Selisih x=3, selisih y=4, jarak = √(3²+4²) = √25 = 5.",hint:"Hitung dulu selisih koordinat x dan selisih koordinat y sebelum mengkuadratkan."},
{n:43,type:"mcq",micro:"Rumus titik tengah",q:"Hitung titik tengah antara (2, 4) dan (8, 10).",options:["(6, 6)","(5, 7)","(10, 14)"],answer:1,explain:"Titik tengah = ((2+8)/2, (4+10)/2) = (5, 7).",hint:"Rata-ratakan kedua koordinat x, lalu rata-ratakan kedua koordinat y secara terpisah."},
{n:44,type:"mcq",micro:"Rumus titik tengah dengan koordinat negatif",q:"Hitung titik tengah antara (-2, 3) dan (6, -1).",options:["(4, 2)","(-2, 1)","(2, 1)"],answer:2,explain:"Titik tengah = ((-2+6)/2, (3+(-1))/2) = (2, 1).",hint:"Jumlahkan kedua koordinat x (termasuk tandanya), baru bagi dua; lakukan hal yang sama untuk koordinat y."},
{n:45,type:"mcq",micro:"Refleksi terhadap sumbu-x",q:"Titik (3, 7) dicerminkan terhadap sumbu-x. Apa koordinat bayangannya?",options:["(3, -7)","(-3, 7)","(-3, -7)"],answer:0,explain:"Refleksi terhadap sumbu-x membalik tanda koordinat y, sementara koordinat x tetap sama.",hint:"Refleksi terhadap sumbu-x mengubah tanda koordinat yang mana?"},
{n:46,type:"mcq",micro:"Refleksi terhadap sumbu-y",q:"Titik (-5, 2) dicerminkan terhadap sumbu-y. Apa koordinat bayangannya?",options:["(-5, -2)","(5, 2)","(5, -2)"],answer:1,explain:"Refleksi terhadap sumbu-y membalik tanda koordinat x, sementara koordinat y tetap sama.",hint:"Refleksi terhadap sumbu-y mengubah tanda koordinat yang mana?"},
{n:47,type:"mcq",micro:"Menghitung hasil translasi",q:"Titik (4, -3) ditranslasikan 2 satuan ke kanan dan 5 satuan ke atas. Apa koordinat barunya?",options:["(2, 2)","(6, -8)","(6, 2)"],answer:2,explain:"Tambahkan 2 pada koordinat x (4+2=6) dan tambahkan 5 pada koordinat y (−3+5=2).",hint:"Ke kanan berarti menambah koordinat x, dan ke atas berarti menambah koordinat y."},
{n:48,type:"order",micro:"Mengurutkan langkah rumus jarak",q:"Urutkan langkah-langkah untuk mencari jarak antara titik A(1, 2) dan B(4, 6) menggunakan rumus jarak.",items:["Jumlahkan hasil kuadrat tersebut, lalu hitung akar kuadratnya: √(9+16) = 5","Hitung selisih koordinat x dan y: (4−1)=3 dan (6−2)=4","Kuadratkan masing-masing selisih tersebut: 3²=9 dan 4²=16"],answer:[1,2,0],explain:"Mulai dari selisih koordinat, lalu kuadratkan, baru jumlahkan dan akarkan.",hint:"Bisakah kamu mengkuadratkan selisihnya sebelum menghitung selisih itu sendiri?"},
{n:49,type:"mcq",micro:"Kuadran dari tanda koordinat",q:"Tentukan kuadran dari titik yang memiliki koordinat x negatif dan koordinat y positif.",options:["Kuadran II","Kuadran I","Kuadran III"],answer:0,explain:"x negatif dan y positif menunjukkan posisi kiri-atas, yaitu Kuadran II.",hint:"x negatif berarti ke kiri, dan y positif berarti ke atas — kuadran mana itu?"},
{n:50,type:"mcq",micro:"Kuadran dari tanda koordinat",q:"Tentukan kuadran dari titik yang memiliki koordinat x positif dan koordinat y negatif.",options:["Kuadran I","Kuadran IV","Kuadran III"],answer:1,explain:"x positif dan y negatif menunjukkan posisi kanan-bawah, yaitu Kuadran IV.",hint:"x positif berarti ke kanan, dan y negatif berarti ke bawah — kuadran mana itu?"},
{n:51,type:"mcq",micro:"Mengenali garis sejajar dari kemiringan",q:"Garis 1 memiliki kemiringan (slope) 2. Garis 2 memiliki kemiringan 2 juga, tetapi melalui titik yang berbeda. Apa hubungan kedua garis ini?",options:["Tegak lurus","Berpotongan di banyak titik","Sejajar"],answer:2,explain:"Dua garis dengan kemiringan yang sama persis, namun melalui titik berbeda, selalu sejajar.",hint:"Apakah kemiringan yang sama persis berarti kedua garis naik/turun dengan kecepatan yang sama?"},
{n:52,type:"mcq",micro:"Mengenali garis tegak lurus dari kemiringan",q:"Garis 1 memiliki kemiringan 3. Garis 2 memiliki kemiringan -1/3. Apa hubungan kedua garis ini?",options:["Tegak lurus (karena hasil kali kedua kemiringan adalah -1)","Sejajar","Merupakan garis yang sama"],answer:0,explain:"3 × (−1/3) = −1, dan hasil kali kemiringan −1 adalah ciri dua garis yang tegak lurus.",hint:"Kalikan kedua kemiringan tersebut — apakah hasilnya -1?"},
{n:53,type:"mcq",micro:"Rumus jarak dengan angka lebih besar",q:"Hitung jarak antara titik (0, 5) dan (12, 0).",options:["17 satuan","13 satuan","7 satuan"],answer:1,explain:"Jarak = √(12² + 5²) = √(144+25) = √169 = 13.",hint:"Hitung selisih x dan selisih y dulu, lalu kuadratkan masing-masing sebelum menjumlahkan."},
{n:54,type:"mcq",micro:"Mencari titik ujung dari titik tengah",q:"Sebuah segmen garis memiliki titik ujung A(2, 3) dan titik tengah M(5, 6). Berapa koordinat titik ujung lainnya, B?",options:["(3.5, 4.5)","(7, 9)","(8, 9)"],answer:2,explain:"Karena M=(A+B)/2, maka B=2M−A=(10−2, 12−3)=(8, 9).",hint:"Kalikan koordinat titik tengah dengan 2, lalu kurangkan koordinat titik A yang sudah diketahui."},
{n:55,type:"mcq",micro:"Translasi dengan pengurangan",q:"Titik (6, -2) ditranslasikan 4 satuan ke kiri dan 3 satuan ke bawah. Apa koordinat barunya?",options:["(2, -5)","(10, -5)","(2, 1)"],answer:0,explain:"Kurangkan 4 dari koordinat x (6−4=2) dan kurangkan 3 dari koordinat y (−2−3=−5).",hint:"Ke kiri berarti mengurangi koordinat x, dan ke bawah berarti mengurangi koordinat y."},
{n:56,type:"classify",micro:"Sejajar, tegak lurus, atau bukan keduanya?",q:"Kelompokkan setiap pasangan garis berikut sebagai 'Sejajar', 'Tegak Lurus', atau 'Bukan Keduanya'.",items:["Kemiringan 2 dan kemiringan 2","Kemiringan 4 dan kemiringan -1/4","Kemiringan 3 dan kemiringan 5","Kemiringan -2 dan kemiringan 2"],groups:["Sejajar","Tegak Lurus","Bukan Keduanya"],answer:{"Sejajar":["Kemiringan 2 dan kemiringan 2"],"Tegak Lurus":["Kemiringan 4 dan kemiringan -1/4"],"Bukan Keduanya":["Kemiringan 3 dan kemiringan 5","Kemiringan -2 dan kemiringan 2"]},explain:"Sejajar jika kemiringannya sama persis; tegak lurus jika hasil kali kemiringannya -1; selain itu, bukan keduanya.",hint:"Periksa apakah kedua kemiringan sama persis, atau apakah hasil kalinya tepat -1."},
{n:57,type:"mcq",micro:"Dua refleksi berturut-turut",q:"Titik (3, 4) dicerminkan terhadap sumbu-x, menghasilkan (3, -4). Titik tersebut kemudian dicerminkan lagi terhadap sumbu-y. Apa koordinat akhirnya?",options:["(3, 4)","(-3, -4)","(-3, 4)"],answer:1,explain:"Refleksi kedua terhadap sumbu-y membalik tanda koordinat x dari (3,-4) menjadi (-3,-4).",hint:"Dari titik (3, -4), refleksi terhadap sumbu-y mengubah tanda koordinat yang mana?"},
{n:58,type:"mcq",micro:"Jarak dengan koordinat y sama",q:"Berapa jarak antara dua titik yang memiliki koordinat y yang sama, yaitu (2, 5) dan (9, 5)?",options:["5 satuan","14 satuan","7 satuan"],answer:2,explain:"Karena koordinat y sama, jaraknya adalah selisih koordinat x: 9−2=7.",hint:"Karena koordinat y kedua titik sama, cukup hitung selisih koordinat x saja."},
{n:59,type:"mcq",micro:"Rumus umum titik tengah",q:"Apa rumus umum untuk mencari titik tengah antara titik (x1, y1) dan (x2, y2)?",options:["((x1+x2)/2, (y1+y2)/2)","(x1+x2, y1+y2)","((x1−x2)/2, (y1−y2)/2)"],answer:0,explain:"Titik tengah adalah rata-rata dari kedua koordinat x dan rata-rata dari kedua koordinat y.",hint:"Titik tengah adalah hasil rata-rata (jumlah dibagi 2), bukan hasil penjumlahan saja."},
{n:60,type:"mcq",micro:"Langkah pertama rumus jarak",q:"Untuk mencari jarak antara dua titik yang TIDAK berada pada garis horizontal atau vertikal yang sama, langkah pertama apa yang harus dilakukan?",options:["Menjumlahkan koordinat x dan y kedua titik lalu membaginya dengan dua","Menghitung selisih koordinat x dan selisih koordinat y di antara kedua titik","Mengukur dengan penggaris pada gambar tanpa memakai koordinat sama sekali"],answer:1,explain:"Rumus jarak selalu dimulai dengan menghitung selisih koordinat x dan y sebelum mengkuadratkan dan menjumlahkannya.",hint:"Sebelum mengkuadratkan atau menjumlahkan apa pun, apa yang perlu dihitung terlebih dahulu dari kedua titik?"},
{n:61,type:"mcq",micro:"Mengapa GPS butuh dua angka",q:"Mengapa sistem GPS pada ponsel menggunakan dua angka (lintang dan bujur) untuk menunjukkan lokasimu, bukan hanya satu angka?",options:["Karena satu angka cukup untuk menentukan lokasi, dan angka kedua hanya untuk mempercantik tampilan aplikasi","Karena ponsel memiliki dua antena, dan masing-masing antena perlu satu angka untuk mencatat lokasi","Karena permukaan bumi memiliki dua arah independen yang harus ditentukan bersamaan agar lokasi tepat"],answer:2,explain:"Posisi pada permukaan bumi (mirip bidang datar) membutuhkan dua koordinat independen agar tepat.",hint:"Apakah satu angka saja bisa menunjukkan posisi yang sebenarnya membutuhkan dua arah berbeda?"},
{n:62,type:"open",micro:"Analisis kesalahan",q:"Seorang siswa mencari jarak antara titik (1, 2) dan (4, 6) dengan menulis: jarak = (4−1) + (6−2) = 3 + 4 = 7. Temukan kesalahannya dan jelaskan cara yang benar.",explain:"Menjumlahkan selisih koordinat secara langsung adalah kesalahan umum yang melewatkan langkah kuadrat dan akar pada rumus jarak.",hint:"Apakah rumus jarak yang benar hanya menjumlahkan selisih koordinat, atau melibatkan langkah kuadrat dan akar?",sample:"Siswa tersebut hanya menjumlahkan selisihnya secara langsung, padahal rumus jarak yang benar melibatkan mengkuadratkan setiap selisih, menjumlahkannya, lalu mengambil akar kuadratnya: jarak = √(3² + 4²) = √(9+16) = √25 = 5, bukan 7."},
{n:63,type:"open",micro:"Memeriksa hasil titik tengah",q:"Setelah menghitung titik tengah antara (2, 8) dan (6, 2) dan mendapatkan (4, 5), bagaimana cara memeriksa apakah jawaban ini benar?",explain:"Titik tengah yang benar harus berjarak sama persis dari kedua titik asal.",hint:"Apakah jarak dari titik tengah ke masing-masing titik asal seharusnya sama persis?",sample:"Periksa apakah titik tengah (4,5) benar-benar berada tepat di antara kedua titik asal — jarak dari (2,8) ke (4,5) harus sama dengan jarak dari (4,5) ke (6,2); menghitung kedua jarak tersebut dan membandingkannya akan mengonfirmasi apakah titik tengahnya benar."},
{n:64,type:"mcq",micro:"Kegunaan jarak garis lurus pada peta",q:"Sebuah aplikasi peta menampilkan jarak antara dua lokasi sebagai garis lurus, padahal jalan sebenarnya berkelok-kelok. Mengapa jarak garis lurus ini tetap berguna untuk ditampilkan?",options:["Karena jarak garis lurus memberi gambaran perkiraan seberapa dekat dua lokasi tersebut, meskipun jarak tempuh sebenarnya di jalan mungkin lebih jauh","Karena jarak garis lurus menunjukkan panjang jalan sebenarnya yang akan ditempuh pengendara, jadi tidak ada perbedaan dengan jarak tempuh nyata di jalan","Karena aplikasi peta tidak mampu menghitung jarak jalan, sehingga hanya bisa menampilkan garis lurus sebagai satu-satunya jarak yang tersedia"],answer:0,explain:"Jarak garis lurus adalah perkiraan kedekatan yang berguna, meskipun bukan jarak tempuh sebenarnya di jalan.",hint:"Apakah mengetahui perkiraan kedekatan dua lokasi tetap berguna, walau bukan jarak tempuh persis di jalan?"},
{n:65,type:"open",micro:"Penalaran dunia nyata (desain grafis)",q:"Mengapa aplikasi desain grafis (seperti untuk membuat logo) menggunakan koordinat untuk menempatkan setiap elemen gambar, bukan hanya mendeskripsikannya dengan kata-kata seperti 'agak ke kanan'?",explain:"Koordinat memberikan presisi dan konsistensi yang tidak bisa diberikan oleh deskripsi kata-kata yang samar.",hint:"Apakah deskripsi seperti 'agak ke kanan' bisa ditafsirkan sama persis oleh dua orang yang berbeda?",sample:"Koordinat memberikan posisi yang tepat dan bisa diulang persis sama setiap saat, sedangkan deskripsi seperti 'agak ke kanan' bersifat tidak presisi dan bisa ditafsirkan berbeda-beda oleh orang atau program yang berbeda."},
{n:66,type:"mcq",micro:"Efisiensi rumus jarak",q:"Mengapa lebih efisien menggunakan rumus jarak yang sama untuk menghitung jarak antara BANYAK pasangan titik yang berbeda, dibandingkan mencari cara baru setiap kali?",options:["Karena setiap pasangan titik membutuhkan rumus yang berbeda, sehingga rumus yang sama tidak boleh dipakai untuk banyak pasangan","Karena rumus jarak bekerja secara konsisten untuk pasangan titik mana pun, tanpa perlu strategi baru setiap kali","Karena rumus jarak hanya berlaku untuk satu pasangan titik tertentu, dan harus dicari lagi untuk pasangan lainnya"],answer:1,explain:"Satu rumus yang konsisten berlaku untuk semua pasangan titik jauh lebih efisien daripada mencari metode baru setiap kali.",hint:"Apakah rumus jarak yang sama bisa dipakai berulang kali untuk pasangan titik yang berbeda-beda?"},
{n:67,type:"open",micro:"Menyelidiki perbedaan hasil",q:"Dua siswa menghitung jarak antara titik (0,0) dan (6,8) dan mendapatkan hasil 10 dan 14. Buatlah rencana langkah demi langkah untuk menemukan jawaban yang benar.",explain:"Menghitung ulang dengan teliti menggunakan rumus yang benar adalah cara paling andal untuk menemukan jawaban yang tepat.",hint:"Apakah menghitung ulang dengan rumus jarak yang lengkap (kuadrat, jumlah, akar) akan menunjukkan jawaban mana yang benar?",sample:"Hitung ulang dengan teliti: jarak = √(6²+8²) = √(36+64) = √100 = 10 — ini mengonfirmasi 10 sebagai jawaban yang benar; siswa yang mendapat 14 kemungkinan hanya menjumlahkan 6+8 tanpa mengkuadratkan dan mengakarkan terlebih dahulu."},
{n:68,type:"mcq",micro:"Pentingnya sejajar/tegak lurus dalam bangunan",q:"Mengapa mengetahui apakah dua garis sejajar atau tegak lurus berguna dalam desain bangunan (misalnya untuk memastikan dinding benar-benar tegak lurus terhadap lantai)?",options:["Karena sejajar atau tegak lurus hanya soal tampilan gambar di kertas rancangan, sehingga tidak berpengaruh pada kekokohan bangunan sebenarnya","Karena dinding yang tidak sejajar atau tidak tegak lurus justru lebih kokoh, sehingga arsitek sengaja menghindarinya di dalam desain bangunan","Karena hubungan sejajar/tegak lurus yang tepat memastikan struktur bangunan kokoh dan sesuai rencana, sementara kesalahan kecil bisa menyebabkan masalah struktural nyata"],answer:2,explain:"Ketepatan sejajar dan tegak lurus adalah dasar penting bagi kekuatan dan kesesuaian struktur bangunan nyata.",hint:"Bisakah dinding yang tidak benar-benar tegak lurus terhadap lantai menyebabkan masalah struktural nyata?"},
{n:69,type:"open",micro:"Titik tengah untuk keputusan yang adil",q:"Mengapa mengetahui titik tengah antara dua lokasi bisa membantu dua orang yang tinggal jauh berbeda memutuskan tempat bertemu yang adil?",explain:"Titik tengah secara matematis menjamin jarak yang sama bagi kedua pihak, sebuah alasan nyata untuk keadilan.",hint:"Apakah titik tengah menjamin jarak yang sama persis dari kedua orang tersebut?",sample:"Titik tengah memberikan lokasi yang jaraknya sama persis dari kedua orang, sehingga tidak ada satu pihak yang harus menempuh perjalanan jauh sementara pihak lain hanya menempuh jarak dekat — ini membuat keputusan tempat bertemu terasa lebih adil bagi keduanya."},
{n:70,type:"mcq",micro:"Mengapa hasil kali kemiringan tegak lurus selalu -1",q:"Mengapa hasil kali kemiringan dua garis yang saling tegak lurus selalu -1 (bukan angka lain)?",options:["Karena ini adalah hubungan matematis yang konsisten yang mendefinisikan tegak lurus pada bidang koordinat — setiap pasangan garis tegak lurus akan selalu memenuhi hubungan ini","Karena angka -1 dipilih secara acak oleh matematikawan, dan tidak ada hubungan khusus antara kemiringan dua garis yang saling tegak lurus pada bidang koordinat","Karena hasil kali kemiringan dua garis tegak lurus bergantung pada panjang garisnya, sehingga angkanya bisa berbeda untuk tiap pasangan garis yang dibandingkan"],answer:0,explain:"Hubungan hasil kali -1 adalah definisi matematis yang konsisten untuk garis tegak lurus, bukan kebetulan.",hint:"Apakah hubungan ini berlaku secara konsisten untuk SETIAP pasangan garis tegak lurus, atau hanya kebetulan pada beberapa contoh?"},
{n:71,type:"open",micro:"Perkiraan sebagai pemeriksa kesalahan",q:"Sebelum menghitung jarak antara (1,1) dan (5,4) secara tepat, bagaimana perkiraan kasar bisa membantu memeriksa kesalahan?",explain:"Perkiraan kasar berfungsi sebagai pemeriksaan kewajaran terhadap hasil perhitungan yang tepat.",hint:"Apakah selisih besar antara perkiraan kasar dan hasil perhitungan tepat patut dicurigai?",sample:"Secara kasar, selisih x adalah 4 dan selisih y adalah 3, jadi jaraknya seharusnya sedikit lebih dari 4 (karena menggabungkan pergerakan diagonal); jika hasil perhitungan tepatmu memberikan angka yang jauh berbeda seperti 20, itu adalah tanda bahwa ada yang salah dalam perhitungan."},
{n:72,type:"mcq",micro:"Mengenali pola garis sejajar",q:"Melihat beberapa pasangan garis dengan kemiringan yang sama tetapi memotong sumbu-y di titik berbeda, pola apa yang selalu muncul?",options:["Garis-garis tersebut kadang sejajar dan kadang tidak, tergantung situasi","Garis-garis tersebut selalu sejajar dan tidak akan pernah berpotongan","Garis-garis tersebut akan selalu berpotongan pada akhirnya"],answer:1,explain:"Kemiringan yang sama selalu menghasilkan garis-garis yang sejajar, secara konsisten pada setiap contoh.",hint:"Apakah pola ini berlaku sama untuk SETIAP pasangan garis dengan kemiringan sama, atau berubah-ubah?"},
{n:73,type:"open",micro:"Refleksi pilihan strategi",q:"Ceritakan situasi nyata di mana perkiraan jarak secara kasar (dari melihat peta) sudah cukup, dan situasi lain di mana kamu membutuhkan jarak yang dihitung secara tepat menggunakan rumus.",explain:"Mengenali kapan presisi benar-benar penting, dan kapan perkiraan kasar sudah cukup, mencerminkan penilaian matematis yang matang.",hint:"Apakah perkiraan kasar berisiko dalam situasi yang membutuhkan presisi tinggi, tetapi cukup untuk situasi santai?",sample:"Untuk hal seperti memperkirakan apakah dua toko cukup dekat untuk dikunjungi dalam satu perjalanan, perkiraan kasar dari peta sudah cukup; tetapi untuk hal seperti menghitung jarak tepat yang dibutuhkan pesawat tanpa awak (drone) agar baterainya cukup, perhitungan jarak yang tepat menggunakan rumus jauh lebih penting."},
{n:74,type:"mcq",micro:"Arti tanda perkiraan (≈)",q:"Sebuah aplikasi menampilkan jarak antar dua kota sebagai '≈150 km'. Apa arti tanda '≈' pada angka tersebut?",options:["Jarak sebenarnya persis 150 km, karena tanda '≈' hanya hiasan dan tidak mengubah angka tertulis","Jarak sebenarnya jauh lebih dari 150 km, karena tanda '≈' berarti angka sebenarnya lebih besar","Jarak sebenarnya kemungkinan mendekati 150 km, tetapi tidak selalu tepat persis 150 km"],answer:2,explain:"Tanda '≈' menandakan sebuah perkiraan, bukan angka yang pasti dan tepat.",hint:"Apakah tanda '≈' biasanya menunjukkan angka yang pasti, atau sebuah perkiraan?"},
{n:75,type:"open",micro:"Bekerja teliti di bawah tekanan waktu",q:"Saat mengerjakan soal ujian dengan batas waktu yang melibatkan banyak perhitungan jarak dan titik tengah, kebiasaan apa yang membantu menghindari kesalahan ceroboh?",explain:"Kebiasaan menuliskan setiap langkah secara eksplisit membantu menjaga akurasi bahkan di bawah tekanan waktu.",hint:"Apakah menuliskan setiap langkah rumus secara terpisah membantu menghindari kesalahan urutan saat terburu-buru?",sample:"Selalu menuliskan setiap langkah rumus secara eksplisit (menghitung selisih dulu, baru mengkuadratkan, baru menjumlahkan, baru mengakarkan) alih-alih mencoba menghitung semuanya sekaligus di kepala, membantu menghindari kesalahan urutan langkah saat terburu-buru."},
{n:76,type:"mcq",micro:"Koordinat pada aplikasi pengiriman",q:"Mengapa aplikasi pengiriman makanan sering menampilkan estimasi jarak dan waktu tempuh berdasarkan lokasi koordinat pelanggan dan restoran?",options:["Karena koordinat memungkinkan aplikasi menghitung jarak secara otomatis dan konsisten untuk memberi estimasi yang berguna bagi pelanggan dan kurir","Karena koordinat membuat pelanggan dan kurir wajib berjalan lurus sepanjang garis jarak, sehingga estimasi itu selalu tepat sampai satuan menit","Karena aplikasi tidak bisa menghitung jarak dari koordinat, sehingga estimasi dibuat berdasarkan tebakan petugas yang mengirim makanan"],answer:0,explain:"Koordinat memungkinkan perhitungan otomatis dan konsisten, sebuah keuntungan nyata untuk estimasi pengiriman.",hint:"Apakah menggunakan koordinat memungkinkan perhitungan jarak yang otomatis dan konsisten untuk setiap pesanan?"},
{n:77,type:"open",micro:"Menjelaskan aturan refleksi ke orang lain",q:"Seorang teman bingung mengapa mencerminkan titik terhadap sumbu-x hanya mengubah tanda koordinat y, bukan koordinat x. Apa yang akan kamu jelaskan, dan mengapa itu membantu?",explain:"Menghubungkan aturan aljabar abstrak dengan gambaran cermin yang konkret menunjukkan pemahaman yang mendalam, bukan hafalan semata.",hint:"Apakah sumbu-x bisa dibayangkan sebagai 'cermin' itu sendiri, sehingga jarak terhadapnya yang berubah adalah jarak vertikal?",sample:"Saya akan menjelaskan bahwa sumbu-x bertindak seperti 'cermin' itu sendiri, sehingga jarak horizontal (koordinat x) titik terhadap cermin tidak berubah, sementara jarak vertikal (koordinat y) dibalik ke sisi yang berlawanan — menghubungkan aturan aljabar dengan gambaran cermin yang konkret membantu aturan tersebut terasa masuk akal, bukan sekadar dihafal."},
{n:78,type:"mcq",micro:"Mengenali hasil yang tidak mungkin",q:"Kamu menghitung jarak antara dua titik dan mendapatkan hasil negatif, seperti -5. Apa yang ini tunjukkan?",options:["Hasil itu wajar, karena jarak bisa negatif bila arah perjalanan menuju ke belakang","Pasti ada kesalahan perhitungan, karena jarak tidak pernah bernilai negatif","Hasil itu menunjukkan dua titik berada di sisi berlawanan, jadi jaraknya benar -5"],answer:1,explain:"Jarak selalu bernilai positif atau nol; hasil negatif menandakan ada kesalahan dalam perhitungan.",hint:"Bisakah jarak antara dua titik yang berbeda bernilai negatif dalam kondisi apa pun?"},
{n:79,type:"open",micro:"Merancang sistem yang adil",q:"Rancang cara sederhana bagi sebuah kelas untuk menghindari kesalahan umum saat menghitung jarak dan titik tengah, seperti lupa mengakarkan hasil pada rumus jarak.",explain:"Sistem menuliskan langkah secara eksplisit dan memeriksa kewajaran hasil adalah cara praktis mencegah kesalahan umum ini.",hint:"Apakah mewajibkan setiap langkah rumus dituliskan secara terpisah akan membantu menangkap langkah yang terlewat?",sample:"Mewajibkan siswa menuliskan setiap langkah rumus secara terpisah dan diberi label (hitung selisih, kuadratkan, jumlahkan, akarkan), serta memeriksa apakah jawaban akhir masuk akal dibandingkan perkiraan kasar dari gambar, sebelum dianggap selesai."},
{n:80,type:"mcq",micro:"Memeriksa keyakinan dari beberapa percobaan",q:"Kamu menghitung jarak yang sama sebanyak tiga kali dan mendapatkan hasil 5, 5, dan 7. Langkah apa yang paling masuk akal selanjutnya?",options:["Terima 7 sebagai jawaban benar karena hasil terakhir selalu paling cermat, dan abaikan dua hasil 5 sebelumnya tanpa memeriksa ulang perhitungan apa pun yang dilakukan","Ambil rata-rata ketiganya (sekitar 5,7) sebagai jawaban akhir tanpa memeriksa perhitungan mana yang benar atau salah dalam ketiga percobaan yang dilakukan","Periksa kembali perhitungan ketiga yang menghasilkan 7, karena dua hasil yang sama (5) lebih mungkin benar, tetapi tetap perlu diverifikasi, bukan langsung dipercaya begitu saja"],answer:2,explain:"Hasil yang muncul lebih sering lebih mungkin benar, tetapi tetap perlu diverifikasi dengan menghitung ulang, bukan langsung dipercaya.",hint:"Apakah hasil yang muncul dua kali otomatis benar, ataukah tetap perlu diperiksa ulang?"},
{n:81,type:"open",micro:"Masalah nyata multi-langkah",q:"Dua menara sinyal berada di koordinat (0, 0) dan (30, 40) pada peta (dalam kilometer). Hitunglah jarak lurus antara kedua menara tersebut.",explain:"Menerjemahkan posisi dua menara ke dalam koordinat, lalu menerapkan rumus jarak, memberikan jarak sebenarnya.",hint:"Berapa selisih koordinat x dan selisih koordinat y antara kedua menara?",sample:"Menggunakan rumus jarak: jarak = √(30² + 40²) = √(900+1600) = √2500 = 50 km."},
{n:82,type:"open",micro:"Merancang cara memeriksa hasil",q:"Rancang cara cepat untuk memeriksa jawaban temanmu tentang jarak antara dua titik, tanpa mengulang seluruh perhitungannya dari awal.",explain:"Perkiraan kasar sebagai pemeriksaan awal, diikuti verifikasi penuh jika diperlukan, adalah cara praktis dan cepat.",hint:"Apakah perkiraan kasar bisa langsung menunjukkan jika jawaban temanmu tampak tidak masuk akal?",sample:"Lakukan perkiraan kasar terlebih dahulu (misalnya membandingkan selisih x dan y dengan jarak yang mereka dapatkan untuk melihat apakah masuk akal), lalu jika ragu, hitung ulang menggunakan rumus jarak secara lengkap dan bandingkan hasilnya dengan jawaban teman tersebut."},
{n:83,type:"open",micro:"Menyelidiki klaim yang tampak aneh",q:"Sebuah buku teks menyatakan bahwa titik (0,0) yang dicerminkan terhadap sumbu manapun akan tetap berada di (0,0). Seorang siswa merasa ini aneh karena mengira pencerminan selalu mengubah posisi. Bagaimana kamu menyelidiki klaim ini?",explain:"Mencoba langsung dengan angka nyata mengungkap bahwa ini adalah kasus khusus yang valid, bukan kesalahan.",hint:"Karena titik (0,0) berada tepat pada kedua sumbu, berapa jaraknya terhadap 'cermin' tersebut?",sample:"Mencoba pencerminan titik (0,0) terhadap sumbu-x menghasilkan (0,-0)=(0,0), dan terhadap sumbu-y menghasilkan (-0,0)=(0,0) — karena titik (0,0) berada tepat PADA kedua sumbu tersebut, jaraknya ke 'cermin' adalah nol, sehingga pencerminannya tidak mengubah posisinya sama sekali, sebuah kasus khusus yang masuk akal setelah diperiksa."},
{n:84,type:"open",micro:"Koneksi sejarah/budaya",q:"Cari tahu (atau ingat kembali) bagaimana sistem lintang dan bujur digunakan sejak lama untuk menentukan lokasi di permukaan bumi, sebelum adanya GPS modern.",explain:"Menghubungkan sistem koordinat modern dengan sejarah panjang lintang-bujur menunjukkan akar nyata dari konsep ini.",hint:"Pernahkah kamu mendengar tentang alat navigasi kuno seperti astrolabe yang digunakan pelaut untuk menentukan posisi?",sample:"Sistem lintang dan bujur sudah digunakan sejak zaman kuno oleh ahli geografi seperti Ptolemy untuk memetakan lokasi di permukaan bumi menggunakan dua angka (mirip sistem koordinat), dan pelaut menggunakan alat seperti astrolabe untuk memperkirakan lintang mereka berdasarkan posisi bintang — menunjukkan bahwa gagasan menentukan posisi dengan dua koordinat sudah ada jauh sebelum teknologi GPS modern."},
{n:85,type:"open",micro:"Masalah nyata multi-langkah",q:"Sebuah taman kota berbentuk persegi panjang memiliki tiga sudut di (1,1), (1,5), dan (6,5). Tentukan koordinat sudut keempat, lalu jelaskan caramu menemukannya.",explain:"Sifat persegi panjang (sisi-sisi sejajar sumbu) memungkinkan sudut keempat ditemukan dengan menggabungkan koordinat yang sudah diketahui.",hint:"Pada persegi panjang, sudut keempat berbagi koordinat x dengan sudut mana, dan koordinat y dengan sudut mana?",sample:"Sudut keempat berada di (6,1) — karena pada persegi panjang, sudut yang berhadapan dengan (1,1) harus memiliki koordinat x yang sama dengan (6,5) dan koordinat y yang sama dengan (1,1), sehingga menggabungkan x=6 dari satu sudut dan y=1 dari sudut lainnya."},
{n:86,type:"open",micro:"Refleksi kesalahan",q:"Ceritakan pengalaman nyata ketika kamu membuat kesalahan terkait koordinat, jarak, atau pencerminan — misalnya salah tanda saat mencerminkan titik, atau lupa mengakarkan pada rumus jarak. Apa yang akan kamu lakukan secara berbeda sekarang?",explain:"Merefleksikan kesalahan nyata dengan perbaikan konkret menunjukkan keterampilan ini benar-benar sudah dipahami.",hint:"Ingat kembali momen ketika jawaban koordinat, jarak, atau pencerminanmu ternyata salah — apa yang sebenarnya salah?",sample:"Bersifat personal dan terbuka — tujuannya adalah mengenali penyebab nyata (seperti salah tanda saat translasi/refleksi, atau lupa langkah akar kuadrat) dan menyebutkan perbaikan konkret, seperti selalu menuliskan setiap langkah rumus secara terpisah."},
{n:87,type:"open",micro:"Merancang proyek kelas",q:"Rancang proyek kelas sederhana untuk 30 siswa agar mempraktikkan koordinat, jarak, dan pencerminan menggunakan peta sekolah atau lingkungan sekitar yang nyata.",explain:"Proyek yang menghubungkan koordinat, rumus jarak, dan pengukuran nyata memberi latihan praktis yang bermakna.",hint:"Apakah membandingkan jarak hitung dengan jarak ukur langsung akan membantu siswa memverifikasi pemahaman mereka?",sample:"Minta kelompok kecil membuat 'peta koordinat' sederhana dari area sekolah (dengan pintu gerbang sebagai titik pusat), menandai beberapa lokasi penting dengan koordinat, menghitung jarak nyata antar lokasi menggunakan rumus jarak, lalu membandingkan hasilnya dengan jarak yang diukur langsung menggunakan langkah kaki atau meteran."},
{n:88,type:"open",micro:"Memperkirakan dan memverifikasi",q:"Perkirakan jarak antara titik (2,3) dan (9,7) dengan perhitungan kasar di kepala, lalu verifikasi dengan perhitungan yang tepat.",explain:"Menerapkan teknik 'perkirakan dulu, verifikasi kemudian' pada rumus jarak yang nyata.",hint:"Apakah perkiraan kasar di kepala bisa memberi gambaran umum sebelum menghitung dengan tepat?",sample:"Perkiraan kasar: selisih x sekitar 7 dan selisih y sekitar 4, jadi jaraknya sedikit lebih dari 7; verifikasi tepat: jarak = √(7²+4²) = √(49+16) = √65 ≈ 8.06, yang memang sedikit lebih besar dari 7, sesuai perkiraan."},
{n:89,type:"open",micro:"Menyelidiki perbedaan hasil nyata",q:"Kamu dan seorang teman menghitung jarak yang sama, tetapi kalkulator temanmu menunjukkan hasil yang sedikit berbeda dari perhitunganmu secara manual. Berikan dua kemungkinan penjelasan, dan bagaimana cara memeriksa masing-masing.",explain:"Mempertimbangkan beberapa penyebab yang mungkin, dan cara memeriksa masing-masing, mencerminkan penalaran investigatif yang baik.",hint:"Bisakah perbedaan ini berasal dari kesalahan input, atau hanya dari pembulatan angka desimal yang berbeda?",sample:"Kemungkinan 1: kesalahan memasukkan koordinat ke dalam kalkulator — periksa ulang apakah koordinat yang dimasukkan sudah benar persis. Kemungkinan 2: perbedaan pembulatan angka desimal antara kalkulator dan perhitungan manual — bandingkan hasil keduanya menggunakan jumlah angka desimal yang sama untuk melihat apakah sebenarnya sudah sesuai."},
{n:90,type:"open",micro:"Koneksi statistik/rata-rata",q:"Sebuah laporan menyatakan 'rata-rata jarak tempuh siswa ke sekolah di suatu kota adalah 3 km.' Mengapa angka rata-rata tunggal ini mungkin tidak menggambarkan situasi setiap siswa secara individu?",explain:"Menghubungkan pemahaman jarak dengan keterbatasan nyata dari sebuah angka rata-rata statistik.",hint:"Apakah mengetahui HANYA rata-rata jarak tempuh memberitahumu jarak tempuh siswa tertentu secara individu?",sample:"Rata-rata menggabungkan banyak jarak tempuh siswa yang berbeda-beda menjadi satu angka — beberapa siswa mungkin tinggal sangat dekat sementara yang lain sangat jauh, sehingga rata-rata 3 km tidak selalu mencerminkan jarak tempuh siswa tertentu secara individu."},
{n:91,type:"open",micro:"Mini proyek",q:"Rancang dan selesaikan sebuah skenario koordinat nyata (seperti mencari jarak antar dua lokasi, titik tengah pertemuan, atau memeriksa apakah dua garis sejajar), lalu tunjukkan langkah kerjamu dengan jelas.",explain:"Penerapan langsung keterampilan koordinat pada tugas nyata yang dirancang sendiri adalah puncak pembelajaran skill ini.",hint:"Apakah menunjukkan setiap langkah kerjamu dengan jelas akan memudahkan orang lain memeriksa hasilnya?",sample:"Bersifat personal dan terbuka — tujuannya adalah mempraktikkan penerapan rumus jarak, titik tengah, atau kemiringan pada skenario realistis yang kamu rancang sendiri."},
{n:92,type:"open",micro:"Menjelaskan ke anak yang lebih muda",q:"Bagaimana kamu akan menjelaskan apa itu 'koordinat' kepada adik yang belum pernah melihat bidang koordinat sama sekali?",explain:"Menghubungkan konsep abstrak koordinat dengan pengalaman konkret yang familiar menunjukkan pemahaman yang mendalam.",hint:"Bisakah mencari kursi bioskop dengan nomor baris dan nomor kursi menjadi contoh yang mirip dengan koordinat?",sample:"Saya akan membandingkannya dengan mencari kursi bioskop menggunakan nomor baris dan nomor kursi — sama seperti kita butuh dua informasi (baris dan nomor kursi) untuk menemukan satu kursi tertentu, koordinat adalah dua angka yang bersama-sama menunjukkan satu titik tertentu pada sebuah bidang datar."},
{n:93,type:"open",micro:"Refleksi alur Konkret-Piktorial-Abstrak",q:"Menurutmu, mengapa memulai dari pengalaman nyata (seperti peta kota atau bayangan cermin) penting sebelum masuk ke rumus jarak dan titik tengah yang abstrak?",explain:"Mencerminkan wawasan sejati tentang mengapa alur Konkret-Piktorial-Abstrak penting khususnya untuk geometri koordinat.",hint:"Apakah rumus jarak akan lebih masuk akal bagi seseorang yang pernah mengalami langsung konsep jarak dan posisi, atau bagi yang hanya menghafal rumus?",sample:"Tanpa pengalaman nyata terlebih dahulu tentang bagaimana posisi, jarak, dan pencerminan sebenarnya terasa (seperti menemukan rumah menggunakan dua arah, atau melihat bayanganmu di cermin), rumus-rumus abstrak bisa terasa seperti sekadar angka yang harus dihafal, bukan sesuatu yang benar-benar menggambarkan posisi dan jarak nyata — membangun dari pengalaman konkret dahulu membantu rumus tersebut menjadi masuk akal kemudian."},
{n:94,type:"open",micro:"Keputusan bisnis dengan koordinat",q:"Sebuah perusahaan pengiriman menemukan bahwa menggunakan koordinat pelanggan untuk menghitung rute pengiriman yang optimal bisa menghemat waktu, tetapi membutuhkan data lokasi yang akurat terlebih dahulu. Keputusan bisnis apa yang mungkin didukung oleh hal ini, dan apa yang perlu diwaspadai?",explain:"Menerapkan penalaran koordinat pada tradeoff bisnis nyata antara investasi data dan efisiensi jangka panjang.",hint:"Apakah rute yang dihitung dari data koordinat yang salah tetap bisa diandalkan?",sample:"Perusahaan mungkin memutuskan investasi dalam sistem pengumpulan data lokasi yang akurat karena penghematan waktu dan biaya pengiriman dalam jangka panjang bisa sangat besar — tetapi perlu diwaspadai bahwa jika data koordinat pelanggan salah atau tidak akurat, perhitungan rute optimal justru akan menyesatkan dan bisa memperlambat pengiriman, bukan mempercepatnya."},
{n:95,type:"open",micro:"Koordinat bertemu keadilan",q:"Tiga sekolah ingin membangun satu perpustakaan bersama di lokasi yang adil bagi ketiganya, berdasarkan koordinat masing-masing sekolah. Jelaskan bagaimana konsep titik tengah (atau titik yang mendekati tengah) bisa membantu keputusan ini.",explain:"Menghubungkan konsep titik tengah dengan diskusi keadilan nyata dalam membagi lokasi bersama.",hint:"Apakah memilih lokasi yang kebetulan paling dekat dengan satu sekolah saja terasa adil bagi sekolah lainnya?",sample:"Menghitung titik tengah dari ketiga koordinat sekolah (rata-rata dari seluruh koordinat x dan rata-rata dari seluruh koordinat y) memberikan satu lokasi yang secara keseluruhan meminimalkan jarak total bagi ketiga sekolah, sehingga lebih adil dibandingkan memilih lokasi yang kebetulan paling dekat dengan salah satu sekolah saja."},
{n:96,type:"open",micro:"Batasan sebuah statistik",q:"Sebuah laporan menyatakan 'rata-rata jarak antar toko cabang suatu perusahaan adalah 5 km.' Apa yang bisa diketahui dari angka ini, dan apa yang tidak bisa diketahui?",explain:"Mengenali bahwa sebuah statistik rata-rata memberi gambaran umum, tetapi bukan gambaran lengkap, adalah koneksi berpikir kritis yang penting.",hint:"Bisakah jarak antar cabang yang sangat bervariasi tetap menghasilkan rata-rata yang sama dengan jarak yang seragam?",sample:"Angka ini bisa menunjukkan kepadatan cabang secara umum — tetapi tidak menunjukkan apakah jarak antar cabang tersebar merata (semua sekitar 5 km) atau sangat bervariasi (ada yang sangat dekat, ada yang sangat jauh) yang kebetulan rata-ratanya tetap 5 km, sehingga tidak cukup untuk menilai strategi lokasi cabang tertentu."},
{n:97,type:"open",micro:"Investigasi nyata multi-langkah",q:"Rancang rencana untuk menentukan, menggunakan koordinat dan rumus jarak, rute berjalan kaki mana yang paling pendek di antara beberapa tempat wisata dalam satu hari, tanpa aplikasi peta digital.",explain:"Menerapkan strategi 'catat koordinat, hitung jarak, bandingkan urutan' pada perencanaan perjalanan nyata.",hint:"Apakah membandingkan total jarak dari beberapa urutan kunjungan yang berbeda akan menunjukkan urutan yang paling pendek?",sample:"Catat koordinat perkiraan setiap tempat wisata pada peta kertas sederhana, hitung jarak antar setiap pasangan tempat menggunakan rumus jarak, lalu bandingkan total jarak dari beberapa kemungkinan urutan kunjungan untuk menemukan urutan dengan total jarak berjalan paling pendek."},
{n:98,type:"open",micro:"Koordinat dan teknologi",q:"Aplikasi peta digital dapat langsung menghitung jarak dan rute tanpa kamu perlu menggunakan rumus jarak secara manual. Apa satu keuntungan dan satu risiko dari terlalu bergantung pada hal ini tanpa memahami cara kerja rumusnya?",explain:"Memperluas penalaran koordinat ke alat digital nyata, menimbang kepraktisan melawan risiko kesalahan yang tidak terdeteksi.",hint:"Jika koordinat yang dimasukkan ke aplikasi salah, akankah aplikasi tersebut memberi peringatan, atau tetap menampilkan hasil yang percaya diri namun salah?",sample:"Keuntungan: perhitungan jarak dan rute yang rumit bisa didapat secara instan, jauh lebih cepat daripada menghitung manual. Risiko: jika koordinat yang dimasukkan salah (misalnya lokasi yang tertukar), kamu mungkin tidak menyadari hasil yang ditampilkan sebenarnya salah, karena tidak memahami bagaimana angka tersebut seharusnya dihitung."},
{n:99,type:"open",micro:"Menyelidiki angka yang berbeda",q:"Dua sumber peta digital menunjukkan jarak yang sedikit berbeda antara dua kota yang sama, misalnya 148 km dan 152 km. Bagaimana seharusnya pembaca yang cermat menyikapi perbedaan ini?",explain:"Menerapkan penalaran investigatif yang adil terhadap angka yang tampak bertentangan, tanpa langsung menuduh salah satu sumber keliru.",hint:"Bisakah dua sumber peta menggunakan titik referensi kota yang sedikit berbeda, sehingga menghasilkan jarak yang sedikit berbeda pula?",sample:"Pembaca yang cermat sebaiknya mempertimbangkan bahwa kedua sumber mungkin menggunakan titik referensi yang sedikit berbeda dalam kota tersebut (seperti pusat kota versus batas kota) atau metode perhitungan yang sedikit berbeda, alih-alih langsung menganggap salah satu sumber pasti keliru, dan bisa memeriksa titik referensi masing-masing sumber sebelum memutuskan mana yang paling sesuai untuk kebutuhannya."},
{n:100,type:"open",micro:"Refleksi kapstone",q:"Melihat kembali keterampilan Geometri Koordinat ini — mulai dari peta kota dan bayangan cermin yang nyata, lalu ke gambar titik-titik pada bidang koordinat, hingga akhirnya ke rumus jarak, titik tengah, dan kemiringan yang abstrak — kebiasaan apa yang sekarang kamu miliki ketika melihat koordinat atau bidang koordinat?",explain:"Menyebutkan kebiasaan baru yang konkret, terkait perjalanan konkret-ke-abstrak dari skill ini, adalah tanda paling jelas bahwa keterampilan ini sudah tertanam.",hint:"Ingat momen dalam unit ini ketika koordinat dan jarak berhenti membutuhkan gambar dan mulai masuk akal sebagai ide abstrak tersendiri.",sample:"Bersifat personal dan terbuka — carilah perubahan nyata, seperti secara otomatis membayangkan posisi suatu titik pada bidang sebelum menghitung, memeriksa hasil rumus jarak dengan perkiraan kasar terlebih dahulu, atau langsung mengenali kuadran suatu titik dari tanda koordinatnya tanpa perlu menggambar."},
];
